import io
import unittest

import six


class SixSmokeTests(unittest.TestCase):
    def test_type_constants(self):
        self.assertIs(six.text_type, str)
        self.assertIs(six.binary_type, bytes)
        self.assertTrue(isinstance("hello", six.string_types))
        self.assertTrue(isinstance(1, six.integer_types))

    def test_moves_imports(self):
        from six.moves import configparser, queue, urllib_parse

        self.assertTrue(hasattr(queue, "Queue"))
        self.assertTrue(hasattr(configparser, "ConfigParser"))
        self.assertEqual(
            urllib_parse.urlparse("https://example.com/path").netloc,
            "example.com",
        )

    def test_dictionary_helpers(self):
        data = {"a": 1, "b": 2}
        self.assertEqual(sorted(six.iterkeys(data)), ["a", "b"])
        self.assertEqual(sorted(six.itervalues(data)), [1, 2])
        self.assertEqual(sorted(six.iteritems(data)), [("a", 1), ("b", 2)])

    def test_binary_and_text_helpers(self):
        self.assertEqual(six.b("A"), b"A")
        self.assertEqual(six.u("A"), "A")
        self.assertEqual(six.int2byte(65), b"A")
        self.assertEqual(six.byte2int(b"A"), 65)
        self.assertEqual(six.ensure_binary("hello"), b"hello")
        self.assertEqual(six.ensure_text(b"hello"), "hello")
        self.assertEqual(six.ensure_str(b"hello"), "hello")

    def test_exec_and_print(self):
        ns = {}
        six.exec_("value = 42", ns)
        self.assertEqual(ns["value"], 42)

        buffer = io.StringIO()
        six.print_("hello", "world", sep=", ", file=buffer)
        self.assertEqual(buffer.getvalue(), "hello, world\n")

    def test_metaclass_and_decorators(self):
        class Meta(type):
            pass

        class Base(six.with_metaclass(Meta, object)):
            pass

        @six.add_metaclass(Meta)
        class Decorated(object):
            pass

        @six.python_2_unicode_compatible
        class Texty(object):
            def __str__(self):
                return "value"

        self.assertIsInstance(Base(), Base)
        self.assertIsInstance(Decorated(), Decorated)
        self.assertEqual(str(Texty()), "value")

    def test_unittest_helpers(self):
        six.assertCountEqual(self, [1, 2], [2, 1])
        six.assertRegex(self, "hello world", r"hello")
        six.assertNotRegex(self, "hello world", r"python")
        with self.assertRaises(AssertionError):
            six.assertRegex(self, "hello world", r"python")


if __name__ == "__main__":
    unittest.main()

